-- Clone LOCAL, partie 3 : les 47 tables de public (colonnes, défauts, contraintes, index, déclencheurs, RLS, droits),
-- relevées en lecture seule sur la production le 28/10 au soir. Les règles viennent ensuite du retour 3 du dépôt.
create table public.lieux (id integer generated by default as identity primary key, nom text not null unique,
  created_at timestamptz not null default now());
create table public.promos (id integer generated by default as identity primary key, lieu_id integer not null references public.lieux(id),
  nom text not null, date_debut date not null, date_fin date, created_at timestamptz not null default now());
create index promos_lieu_idx on public.promos (lieu_id);
create table public.profs (id serial primary key, nom text not null unique, ordre integer not null default 0, created_at timestamptz default now());
create table public.stagiaires (id serial primary key, prenom text not null, ordre integer not null default 0,
  created_at timestamptz default now(), nom text, actif boolean not null default true, date_naissance date,
  promo_id integer not null default promo_courante() references public.promos(id), anonymise_le timestamptz,
  constraint stagiaires_date_naissance_videe check (date_naissance is null),
  constraint stagiaires_promo_prenom_unique unique (promo_id, prenom));
create table public.user_profiles (email text primary key, stagiaire_id integer references public.stagiaires(id) on delete set null,
  prof_id integer references public.profs(id) on delete set null, role text not null check (role = any (array['stagiaire', 'prof', 'admin'])),
  invited_at timestamptz default now(), invited_by_email text, first_login_at timestamptz, is_admin boolean not null default false,
  anonymous_notes boolean not null default false, is_founder boolean not null default false, anon_changed_at timestamptz,
  anon_lock_until timestamptz);
create index user_profiles_prof_idx on public.user_profiles (prof_id);
create index user_profiles_stagiaire_idx on public.user_profiles (stagiaire_id);
create table public.competences (code text primary key, libelle text not null, ordre integer not null default 0);
create table public.themes (id serial primary key, numero integer unique, titre text not null, categorie text,
  type text not null default 'theme' check (type = any (array['theme', 'notion'])),
  statut text not null default 'À faire' check (statut = any (array['À faire', 'En cours', 'Fait'])), date_fait date, notes text,
  ordre integer default 0, updated_by_email text, updated_at timestamptz default now(), date_qcm date, code text unique);
create index idx_themes_statut on public.themes (statut);
create index idx_themes_type on public.themes (type);
create table public.qcm (id bigint generated by default as identity primary key, theme_id integer not null unique references public.themes(id) on delete cascade,
  titre text not null, description text, published boolean not null default false, published_by_email text, published_at timestamptz,
  exam_nb_questions integer, exam_pass_20 numeric not null default 12, created_by_email text, created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(), exam_question_ids jsonb,
  exam_draw_mode text check (exam_draw_mode = any (array['random', 'manual'])), exam_seconds_per_question integer not null default 30,
  exam_ferme_a timestamptz);
create table public.cours (id uuid primary key default gen_random_uuid(), numero integer unique check (numero >= 1 and numero <= 57),
  titre text not null, corps_md text not null, published boolean not null default false, updated_by text,
  updated_at timestamptz not null default now(), created_at timestamptz not null default now(), code text unique,
  constraint cours_code_format check (code is null or code ~ '^C[1-4](\.[1-9])?$'),
  constraint cours_numero_ou_code check ((numero is null) <> (code is null)));
create table public.cours_chunks (id bigint generated always as identity primary key,
  cours_id uuid not null references public.cours(id) on delete cascade, numero integer, titre text not null,
  section text not null default '', contenu text not null, ordre integer not null,
  tsv tsvector generated always as (to_tsvector('french'::regconfig, ((coalesce(section, '') || ' ') || contenu))) stored, code text);
create index cours_chunks_tsv_idx on public.cours_chunks using gin (tsv);
create index cours_chunks_cours_idx on public.cours_chunks (cours_id);
create table public.cours_versions (id uuid primary key default gen_random_uuid(), cours_id uuid not null references public.cours(id),
  titre text not null, corps_md text not null, saved_by text, saved_at timestamptz not null default now());
create index cours_versions_cours_idx on public.cours_versions (cours_id, saved_at desc);
create table public.qcm_ia_brouillons (id bigint generated always as identity primary key,
  qcm_id bigint not null references public.qcm(id) on delete cascade, cours_id uuid references public.cours(id) on delete set null,
  demande_par_email text not null, partie_visee text, section text, enonce text not null, options jsonb not null default '[]',
  explication text, partie_cours text,
  statut text not null default 'a_relire' check (statut = any (array['a_relire', 'acceptee', 'rejetee', 'ecartee'])),
  motif text, traite_par_email text, traite_le timestamptz, modele text, created_at timestamptz not null default now());
create index qcm_ia_brouillons_qcm_idx on public.qcm_ia_brouillons (qcm_id, statut);
create table public.qcm_questions (id bigint generated by default as identity primary key,
  qcm_id bigint not null references public.qcm(id) on delete cascade, section text, enonce text not null, explication text,
  ordre integer not null default 0, created_at timestamptz not null default now(), image_url text,
  ia_brouillon_id bigint references public.qcm_ia_brouillons(id) on delete set null, ia_validee_par text, ia_validee_le timestamptz);
create index qcm_questions_qcm_ordre_idx on public.qcm_questions (qcm_id, ordre);
create table public.qcm_options (id bigint generated by default as identity primary key,
  question_id bigint not null references public.qcm_questions(id) on delete cascade, texte text not null,
  is_correct boolean not null default false, ordre integer not null default 0);
create index qcm_options_question_ordre_idx on public.qcm_options (question_id, ordre);
create table public.qcm_signalements (id bigserial primary key, question_id bigint not null references public.qcm_questions(id) on delete cascade,
  email text not null, stagiaire_id bigint references public.stagiaires(id) on delete set null,
  motif text not null default 'autre' check (motif = any (array['reponse_fausse', 'enonce_ambigu', 'explication', 'doublon', 'autre'])),
  commentaire text, statut text not null default 'ouvert' check (statut = any (array['ouvert', 'traite', 'rejete'])),
  created_at timestamptz not null default now(), traite_at timestamptz, traite_par_email text,
  option_id bigint references public.qcm_options(id) on delete set null, option_texte text);
create index qcm_signalements_question_idx on public.qcm_signalements (question_id);
create index qcm_signalements_statut_idx on public.qcm_signalements (statut);
create table public.qcm_signalement_instruction (signalement_id bigint primary key references public.qcm_signalements(id) on delete cascade,
  verdict_auto text not null check (verdict_auto = any (array['fonde', 'confirme', 'ambigu', 'non_concluant'])),
  analyse_auto text not null, instruit_at timestamptz not null default now());
create table public.qcm_attempts (id bigint generated by default as identity primary key,
  qcm_id bigint not null references public.qcm(id) on delete cascade,
  stagiaire_id integer not null references public.stagiaires(id) on delete cascade,
  mode text not null check (mode = any (array['entrainement', 'examen'])), score integer not null, total integer not null,
  note_20 numeric not null, answers jsonb, started_at timestamptz, finished_at timestamptz not null default now(),
  promo_id integer not null references public.promos(id));
create index qcm_attempts_lookup_idx on public.qcm_attempts (qcm_id, stagiaire_id, mode);
create unique index qcm_attempts_one_exam on public.qcm_attempts (qcm_id, stagiaire_id) where mode = 'examen';
create index qcm_attempts_promo_idx on public.qcm_attempts (promo_id);
create table public.evaluations (id serial primary key, stagiaire_id integer not null references public.stagiaires(id) on delete cascade,
  type text not null check (type = any (array['Thème', 'Compétence', 'Contrôle'])), theme_numero integer, theme_titre text,
  competence_code text references public.competences(code) on delete set null, controle_libelle text, note numeric(5,2),
  note_max numeric(5,2) default 20, observation text, date_eval date not null default current_date, created_by_email text,
  updated_by_email text, created_at timestamptz default now(), updated_at timestamptz default now(),
  qcm_attempt_id bigint references public.qcm_attempts(id) on delete cascade, promo_id integer not null references public.promos(id));
create index idx_eval_date on public.evaluations (date_eval);
create index idx_eval_stagiaire on public.evaluations (stagiaire_id);
create index idx_eval_type on public.evaluations (type);
create index evaluations_promo_idx on public.evaluations (promo_id);
create table public.evaluations_audit (id serial primary key, evaluation_id integer,
  action text not null check (action = any (array['insert', 'update', 'delete'])), before_data jsonb, after_data jsonb,
  changed_by_email text, changed_at timestamptz default now(), promo_id integer not null references public.promos(id));
create index idx_audit_date on public.evaluations_audit (changed_at desc);
create index idx_audit_eval on public.evaluations_audit (evaluation_id);
create index evaluations_audit_promo_idx on public.evaluations_audit (promo_id);
create table public.qcm_examens (promo_id integer not null default promo_courante() references public.promos(id),
  qcm_id bigint not null references public.qcm(id) on delete cascade, published boolean not null default false,
  published_by_email text, published_at timestamptz, exam_nb_questions integer, exam_question_ids jsonb,
  exam_draw_mode text check (exam_draw_mode = any (array['random', 'manual'])), exam_seconds_per_question integer not null default 30,
  exam_ferme_a timestamptz, updated_at timestamptz not null default now(), primary key (promo_id, qcm_id));
create index qcm_examens_qcm_idx on public.qcm_examens (qcm_id);
create table public.themes_progression (promo_id integer not null default promo_courante() references public.promos(id),
  theme_id integer not null references public.themes(id) on delete cascade,
  statut text not null default 'À faire' check (statut = any (array['À faire', 'En cours', 'Fait'])), date_fait date, date_qcm date,
  notes text, updated_by_email text, updated_at timestamptz not null default now(), primary key (promo_id, theme_id));
create index themes_progression_theme_idx on public.themes_progression (theme_id);
create table public.agenda_events (id bigint generated by default as identity primary key, date_start date not null, date_end date,
  type text not null default 'autre', title text not null, description text, location text, created_by_email text,
  created_at timestamptz default now(), updated_at timestamptz default now(),
  promo_id integer not null default promo_courante() references public.promos(id));
create index agenda_events_date_idx on public.agenda_events (date_start);
create index agenda_events_promo_idx on public.agenda_events (promo_id);
create table public.planning_entries (id serial primary key, semaine_lundi date not null,
  day_index integer not null check (day_index >= 0 and day_index <= 4), half_day text not null check (half_day = any (array['matin', 'aprem'])),
  slot integer not null check (slot >= 0),
  activite text constraint valid_activite check (activite is null or activite = any (array['Cours', 'Pédagogie salle', 'Voiture (conduite)', 'Contrôle', 'Autre'])),
  prof_id integer references public.profs(id) on delete set null, sujet text,
  pedagogue_id integer references public.stagiaires(id) on delete set null, eleves_ids integer[] default '{}', notes text,
  created_at timestamptz default now(), updated_at timestamptz default now(), lane integer not null default 0,
  prof_ids integer[] not null default '{}', pedagogue_id_2 integer, eleves_ids_2 integer[] default '{}', salle_double boolean default false,
  benevoles_ids integer[] not null default '{}', prof_autre text, autonomie boolean not null default false, sujet_2 text,
  absences jsonb not null default '[]', promo_id integer not null default promo_courante() references public.promos(id),
  constraint planning_entries_promo_unique unique (promo_id, semaine_lundi, day_index, half_day, slot, lane));
create index idx_planning_semaine on public.planning_entries (semaine_lundi);
create table public.planning_half_meta (id serial primary key, semaine_lundi date not null,
  day_index integer not null check (day_index >= 0 and day_index <= 4), half_day text not null check (half_day = any (array['matin', 'aprem'])),
  start_time text not null, end_time text not null, pause_start text, pause_minutes integer not null default 20,
  updated_at timestamptz default now(), promo_id integer not null default promo_courante() references public.promos(id),
  constraint planning_half_meta_promo_unique unique (promo_id, semaine_lundi, day_index, half_day));
create index idx_half_meta_week on public.planning_half_meta (semaine_lundi);
create table public.planning_jours_off (id bigint generated always as identity primary key, semaine_lundi date not null,
  day_index integer not null check (day_index >= 0 and day_index <= 4), label text, created_at timestamptz default now(),
  created_by_who text, promo_id integer not null default promo_courante() references public.promos(id),
  constraint planning_jours_off_promo_unique unique (promo_id, semaine_lundi, day_index));
create table public.settings (key text not null, value text not null, updated_at timestamptz default now(),
  promo_id integer default promo_courante() references public.promos(id), id bigint generated always as identity primary key,
  constraint settings_globaux_prevus check (promo_id is not null or key = any (array['chatbot_quota_jour', 'cohort_name', 'password_hash'])),
  constraint settings_promo_key_unique unique nulls not distinct (promo_id, key));
create table public.passages (id serial primary key, date date not null,
  stagiaire_id integer not null references public.stagiaires(id) on delete cascade,
  type text not null check (type = any (array['Salle', 'Voiture'])),
  resultat text not null check (resultat = any (array['Effectué', 'Absence', 'Bonus', 'Report'])),
  remplacant_id integer references public.stagiaires(id) on delete set null,
  origine text not null default 'Manuel' check (origine = any (array['Manuel', 'Planning'])), commentaire text, semaine_lundi date,
  created_at timestamptz default now(), created_by_who text, updated_by_who text, prof_id bigint references public.profs(id),
  avec_eleve boolean, promo_id integer not null references public.promos(id));
create index idx_passages_date on public.passages (date);
create index idx_passages_semaine on public.passages (semaine_lundi);
create index idx_passages_stagiaire on public.passages (stagiaire_id);
create index passages_promo_idx on public.passages (promo_id);
create table public.passages_audit (id serial primary key, passage_id integer,
  action text not null check (action = any (array['insert', 'update', 'delete'])), before_data jsonb, after_data jsonb,
  changed_by_who text, changed_at timestamptz default now(), promo_id integer not null references public.promos(id));
create index idx_passages_audit_date on public.passages_audit (changed_at desc);
create index idx_passages_audit_passage on public.passages_audit (passage_id);
create index passages_audit_promo_idx on public.passages_audit (promo_id);
create table public.epcf_evaluations (id bigint generated always as identity primary key,
  stagiaire_id integer not null references public.stagiaires(id) on delete cascade,
  trame text not null check (trame = any (array['salle', 'vehicule'])), trame_version integer not null default 1,
  date_eval date not null default current_date, evaluateur_prof_id integer references public.profs(id),
  auto_eval boolean not null default false, contexte text not null default 'EPCF', meta jsonb not null default '{}',
  scores jsonb not null default '{}' constraint epcf_scores_is_object check (jsonb_typeof(scores) = 'object'),
  competences_acquises jsonb not null default '[]' constraint epcf_competences_is_array check (jsonb_typeof(competences_acquises) = 'array'),
  commentaire text, created_by uuid default auth.uid(), updated_by_who text, created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(), promo_id integer not null references public.promos(id));
create index epcf_evaluations_stagiaire_idx on public.epcf_evaluations (stagiaire_id, trame, date_eval desc);
create index epcf_evaluations_promo_idx on public.epcf_evaluations (promo_id);
create table public.epcf_livrets (id bigint generated always as identity primary key,
  stagiaire_id integer not null unique references public.stagiaires(id) on delete cascade,
  data jsonb not null default '{}' constraint epcf_livrets_data_is_object check (jsonb_typeof(data) = 'object'),
  updated_by_who text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  promo_id integer not null references public.promos(id));
create index epcf_livrets_promo_idx on public.epcf_livrets (promo_id);
create table public.dp_dossiers (id bigint generated always as identity primary key,
  stagiaire_id integer not null unique references public.stagiaires(id) on delete cascade, data jsonb not null default '{}',
  updated_by_who text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  promo_id integer not null references public.promos(id));
create index dp_dossiers_promo_idx on public.dp_dossiers (promo_id);
create table public.fiches_suivi (stagiaire_id bigint primary key references public.stagiaires(id) on delete cascade,
  souhaits jsonb not null default '[]', besoins text, updated_at timestamptz not null default now(), updated_by_who text,
  promo_id integer not null references public.promos(id));
create index fiches_suivi_promo_idx on public.fiches_suivi (promo_id);
create table public.stagiaires_prive (stagiaire_id integer primary key references public.stagiaires(id) on delete cascade,
  date_naissance date, updated_at timestamptz not null default now());
create table public.auto_ecoles (id serial primary key, nom text not null, referent text, telephone text, email text, adresse text,
  notes text, actif boolean not null default true, created_at timestamptz not null default now(),
  lieu_id integer not null default lieu_courant() references public.lieux(id));
create index auto_ecoles_lieu_idx on public.auto_ecoles (lieu_id);
create table public.benevoles (id serial primary key, prenom text not null, nom text, telephone text, niveau text, boite text,
  heures numeric, dispos jsonb not null default '{}', dispo_note text, notes text, actif boolean not null default true,
  created_at timestamptz not null default now(), auto_ecole_id integer references public.auto_ecoles(id),
  lieu_id integer not null default lieu_courant() references public.lieux(id));
create index benevoles_lieu_idx on public.benevoles (lieu_id);
create table public.benevole_suivi (id serial primary key, benevole_id integer not null references public.benevoles(id) on delete cascade,
  semaine_lundi date not null, day_index integer not null, half_day text not null, commentaire text,
  updated_at timestamptz not null default now(), lieu_id integer not null references public.lieux(id),
  unique (benevole_id, semaine_lundi, day_index, half_day));
create index benevole_suivi_lieu_idx on public.benevole_suivi (lieu_id);
create table public.emargement_seances (id bigserial primary key, promo_id integer not null references public.promos(id),
  jour date not null, demi_journee text not null check (demi_journee = any (array['matin', 'aprem'])),
  debut text not null check (debut ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'), fin text not null check (fin ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  statut text not null default 'ouverte' check (statut = any (array['ouverte', 'close'])), ouverte_le timestamptz not null default now(),
  ouverte_par text not null, close_le timestamptz, close_par text,
  check (debut < fin), check ((statut = 'close') = (close_le is not null)), unique (promo_id, jour, demi_journee));
create table public.emargement_lignes (id bigserial primary key,
  seance_id bigint not null references public.emargement_seances(id) on delete cascade,
  promo_id integer not null references public.promos(id), stagiaire_id integer not null references public.stagiaires(id),
  trace text check (trace is null or (length(trace) <= 20000 and trace ~ '^(M[0-9]{1,3} [0-9]{1,3}(L[0-9]{1,3} [0-9]{1,3})*)+$')),
  signe_le timestamptz, signe_par text, sur_appareil_formateur boolean not null default false, absent boolean not null default false,
  absence_origine text check (absence_origine = any (array['formateur', 'planning', 'non_signe'])),
  observation text check (observation is null or length(observation) <= 200), maj_le timestamptz not null default now(), maj_par text,
  check ((trace is null) = (signe_le is null) and (trace is null) = (signe_par is null)), check (not (absent and trace is not null)),
  check (absent = (absence_origine is not null)), unique (seance_id, stagiaire_id));
create index emargement_lignes_stagiaire on public.emargement_lignes (stagiaire_id);
create table public.emargement_formateurs (id bigserial primary key,
  seance_id bigint not null references public.emargement_seances(id) on delete cascade,
  promo_id integer not null references public.promos(id), nom text not null check (length(btrim(nom)) >= 1 and length(btrim(nom)) <= 80),
  prof_id integer references public.profs(id) on delete set null,
  trace text not null check (length(trace) <= 20000 and trace ~ '^(M[0-9]{1,3} [0-9]{1,3}(L[0-9]{1,3} [0-9]{1,3})*)+$'),
  signe_le timestamptz not null default now(), signe_par text not null);
create unique index emargement_formateurs_nom on public.emargement_formateurs (seance_id, lower(nom));
create index emargement_formateurs_seance on public.emargement_formateurs (seance_id);
create table public.effacements_journal (id bigserial primary key,
  type text not null check (type = any (array['stagiaire', 'promo', 'benevoles'])), cible text not null, fait_par_email text not null,
  fait_le timestamptz not null default now(), details jsonb not null default '{}');
create table public.conditions_acceptations (id bigserial primary key, email text not null, version text not null,
  accepted_at timestamptz not null default now(), unique (email, version));
create index conditions_acceptations_email on public.conditions_acceptations (lower(email));
create table public.contacts (id bigint generated by default as identity primary key, prenom text not null, role text, phone text,
  email text, note text, category text default 'admin', sort_order integer default 100, created_at timestamptz default now(),
  updated_at timestamptz default now());
create table public.ressources (id serial primary key, titre text not null, url text not null, description text,
  categorie text not null, icone text, badge text, ordre integer not null default 0, created_at timestamptz default now());
create index idx_ressources_cat on public.ressources (categorie, ordre);
create table public.chatbot_usage (user_id uuid not null references auth.users(id) on delete cascade,
  jour date not null default ((now() at time zone 'Europe/Paris'))::date, nb integer not null default 0, primary key (user_id, jour));
create table public.qcm_ia_usage (user_id uuid not null references auth.users(id) on delete cascade,
  jour date not null default ((now() at time zone 'Europe/Paris'))::date, nb integer not null default 0, primary key (user_id, jour));
create table public.signalements_app (id bigint generated always as identity primary key, created_at timestamptz not null default now(),
  user_id uuid not null references auth.users(id) on delete cascade, email text not null, nom text,
  role text not null check (role = any (array['stagiaire', 'formateur', 'fondateur'])),
  promo_id integer references public.promos(id) on delete set null,
  message text not null check (char_length(message) >= 3 and char_length(message) <= 2000),
  contexte jsonb not null default '{}' check (jsonb_typeof(contexte) = 'object' and octet_length(contexte::text) <= 16384),
  avec_capture boolean not null default false,
  statut text not null default 'nouveau' check (statut = any (array['nouveau', 'en_cours', 'regle', 'non_retenu'])),
  reponse text check (reponse is null or (char_length(reponse) >= 1 and char_length(reponse) <= 2000)), repondu_le timestamptz,
  suivi_le timestamptz, suivi_lu_le timestamptz, traite_le timestamptz, traite_par_email text);
create index signalements_app_user_idx on public.signalements_app (user_id, created_at desc);
create table public.signalements_app_captures (signalement_id bigint primary key references public.signalements_app(id) on delete cascade,
  image text not null check (char_length(image) <= 700000 and image ~ '^data:image/jpeg;base64,[A-Za-z0-9+/=]+$'));

-- Déclencheurs (ceux de la production).
create trigger agenda_set_updated before update on public.agenda_events for each row execute function agenda_touch_updated();
create trigger trg_lieu_du_benevole before insert or update on public.benevole_suivi for each row execute function imposer_lieu_du_benevole();
