-- RLS sur les 47 tables ; droits de anon et authenticated comme sur la production.
do $$
declare t text;
begin
  for t in select c.relname from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
  foreach t in array array['agenda_events', 'chatbot_usage', 'competences', 'contacts', 'cours', 'cours_chunks', 'cours_versions',
      'epcf_evaluations', 'evaluations', 'evaluations_audit', 'fiches_suivi', 'passages', 'passages_audit', 'planning_entries',
      'planning_half_meta', 'planning_jours_off', 'profs', 'qcm', 'qcm_attempts', 'qcm_ia_brouillons', 'qcm_ia_usage', 'qcm_options',
      'qcm_questions', 'qcm_signalements', 'ressources', 'settings', 'stagiaires', 'themes', 'user_profiles'] loop
    execute format('grant all on public.%I to anon, authenticated', t);
  end loop;
  foreach t in array array['auto_ecoles', 'benevole_suivi', 'benevoles', 'dp_dossiers', 'epcf_livrets', 'qcm_examens',
      'qcm_signalement_instruction', 'themes_progression'] loop
    execute format('grant all on public.%I to authenticated', t);
  end loop;
  foreach t in array array['conditions_acceptations', 'effacements_journal', 'emargement_formateurs', 'emargement_lignes',
      'emargement_seances', 'signalements_app_captures', 'stagiaires_prive'] loop
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;
grant select, delete on public.signalements_app to authenticated;
grant select, references, trigger on public.lieux, public.promos to authenticated;
grant update (nom) on public.promos to authenticated;
grant usage, select on all sequences in schema public to anon, authenticated, service_role;
